   363	  public void clear() {
   364	    this.pluginContext.close();
   365	
   366	    try {
   367	      this.saver.close();
   368	    } catch (final IOException ex) {
   369	      DecompilerContext.getLogger().writeMessage("Failed to close out result saver", IFernflowerLogger.Severity.ERROR, ex);
   370	    }
   371	
   372	    for (final ContextUnit unit : this.units) {
   373	      try {
   374	        unit.close();
   375	      } catch (final Exception ex) {
   376	        DecompilerContext.getLogger().writeMessage("Failed to close context unit " + unit.getName(), IFernflowerLogger.Severity.ERROR, ex);
   377	      }
   378	    }
   379	    this.units.clear();
   380	    this.unitsByClassName.clear();
   381	    this.classes.clear();
   382	  }
