  private static ForkJoinPool.ForkJoinWorkerThreadFactory namingScheme() {
    return pool -> {
      ForkJoinWorkerThread thread = new ForkJoinWorkerThread(pool) {};
      thread.setName("Vineflower-DecompilerThread-" + THREAD_ID.getAndIncrement());

